// LeetCode 127 - Word Ladder
// Transform beginWord into endWord by changing one letter at a time, each intermediate
// word in wordList. Return the number of words in the shortest sequence, or 0.
// Approach: bidirectional BFS, always expanding the smaller frontier; neighbors are
// generated by trying all 26 letters at each position.
// Time: O(N * L * 26) word generations (each O(L) to hash), Space: O(N * L)
use std::collections::HashSet;

pub fn ladder_length(begin: &str, end: &str, words: &[&str]) -> usize {
    let mut dict: HashSet<Vec<u8>> = words.iter().map(|w| w.as_bytes().to_vec()).collect();
    let end_v = end.as_bytes().to_vec();
    if !dict.contains(&end_v) {
        return 0;
    }
    let mut front = HashSet::from([begin.as_bytes().to_vec()]);
    let mut back = HashSet::from([end_v]);
    dict.remove(begin.as_bytes());
    let mut steps = 1;
    while !front.is_empty() && !back.is_empty() {
        if front.len() > back.len() {
            std::mem::swap(&mut front, &mut back);
        }
        let mut next = HashSet::new();
        for w in &front {
            let mut w = w.clone();
            for i in 0..w.len() {
                let orig = w[i];
                for c in b'a'..=b'z' {
                    if c == orig {
                        continue;
                    }
                    w[i] = c;
                    if back.contains(&w) {
                        return steps + 1;
                    }
                    if dict.remove(&w) {
                        next.insert(w.clone());
                    }
                }
                w[i] = orig;
            }
        }
        front = next;
        steps += 1;
    }
    0
}

fn main() {
    let w = ["hot", "dot", "dog", "lot", "log", "cog"];
    assert_eq!(ladder_length("hit", "cog", &w), 5);
    assert_eq!(ladder_length("hit", "cog", &w[..5]), 0);
    println!("ok");
}
